func (appVersion0 *AppVersion) InsertApp(ctx context.Context, exec bob.Executor, related *AppSetter) error {
	var err error

	app1, err := Apps.Insert(related).One(ctx, exec)
	if err != nil {
		return fmt.Errorf("inserting related objects: %w", err)
	}

	_, err = attachAppVersionApp0(ctx, exec, 1, appVersion0, app1)
	if err != nil {
		return err
	}

	appVersion0.R.App = app1
	appVersion0.R.Loaded.App = true

	return nil
}

func (appVersion0 *AppVersion) AttachApp(ctx context.Context, exec bob.Executor, app1 *App) error {
	var err error

	_, err = attachAppVersionApp0(ctx, exec, 1, appVersion0, app1)
	if err != nil {
		return err
	}

	appVersion0.R.App = app1
	appVersion0.R.Loaded.App = true

	return nil
}

